#!/usr/bin/env bash
set -u
if (( $# != 2 )); then printf 'usage: %s WORKER NUL_INPUT\n' "$0" >&2; exit 2; fi
worker=$1; input=$2
if [[ ! -x "$worker" || ! -f "$input" ]]; then printf 'invalid worker or input\n' >&2; exit 2; fi
if xargs -0 -r -n1 -P2 -- "$worker" < "$input"; then status=0; else status=$?; fi
case $status in
  0) printf 'COMPLETE\n'; exit 0 ;;
  123) printf 'CHILD_FAILURE: all schedulable items completed with ordinary errors\n' >&2; exit 1 ;;
  124) printf 'BATCH_ABORTED: child returned 255\n' >&2; exit 1 ;;
  *) printf 'XARGS_FAILURE: status=%s\n' "$status" >&2; exit 1 ;;
esac
```

原题知识说明：
交付子命令退出码协议、xargs汇总状态解释和输入到任务的分配清单。GNU xargs对255等状态有特殊停止语义，不能把每个非零都视作继续处理的普通业务失败；并行执行时还必须区分已启动、已完成和因停止未启动的项目。若子工具有不受控退出码，应由开发提供不丢失原始状态的适配层，而不是统一改为0。验收在第一批、中间批和最后一批分别触发255、普通失败、执行失败及信号终止，核对输入条数等于成功、失败和未执行数量之和，并确认没有后台任务遗留。失败报告保留原始状态与汇总状态，重跑仅接受明确未完成的任务清单；不得因已有若干输出文件便宣布整批通过。

